// endpoint: the principal binds directly and is checked in one place
app.MapGet("/orders", (ClaimsPrincipal user, IOrderStore store) =>
{
    if (user.Identity?.IsAuthenticated != true)
        return Results.Unauthorized();
    return Results.Ok(store.For(user));
});

